from dateutil import parser as dparser
import json

def parse_date(s):
    if s is None: return None
    try:
        return dparser.parse(s, fuzzy=True)
    except Exception:
        return None

# parse grant dates
df['grant_dt'] = df['grant_date'].apply(parse_date)
print('non-null grant:', df['grant_dt'].notna().sum())
