# Identify German cohort
def has_de_inventor(s):
    if not s: return False
    try:
        arr = json.loads(s)
        for inv in arr:
            if inv.get('country_code') == 'DE':
                return True
    except Exception:
        pass
    return False

def patents_info_de(s):
    if not s: return False
    return ('In DE,' in s) or ('DE patent' in s) or ('Germany' in s)

cohort['de_inv'] = cohort['inventor_harmonized'].apply(has_de_inventor)
cohort['de_pi'] = cohort['Patents_info'].apply(patents_info_de)
print('DE by inv:', cohort['de_inv'].sum())
print('DE by patents_info:', cohort['de_pi'].sum())
print('DE either:', (cohort['de_inv'] | cohort['de_pi']).sum())

de_cohort = cohort[cohort['de_inv'] | cohort['de_pi']].copy()
print('cohort size:', len(de_cohort))

# Parse cpc for all DF and extract level-4 prefixes
import time
t0 = time.time()

def extract_l4_prefixes(s):
    if not s: return []
    try:
        arr = json.loads(s)
        prefixes = set()
        for item in arr:
            code = item.get('code')
            if code and len(code) >= 3:
                p = code[:3]
                prefixes.add(p)
        return list(prefixes)
    except Exception:
        return []

df['l4_prefs'] = df['cpc'].apply(extract_l4_prefixes)
